DO $publish$ DECLARE j jsonb := $expected$[{"language":"es","slug":"daigaku-imo-boniato-caramelizado","public_path":"/daigaku-imo-boniato-caramelizado","title":"Daigaku imo: boniato japonés caramelizado en sartén","excerpt":"Daigaku imo con boniato de piel morada, glaseado de azúcar y sésamo negro. Se ablanda al microondas y se dora en sartén, sin una olla de fritura profunda.","summary":"Daigaku imo con boniato de piel morada, glaseado de azúcar y sésamo negro. Se ablanda al microondas y se dora en sartén, sin una olla de fritura profunda.","notes":"<p>El satsumaimo japonés de pulpa amarilla es más firme que muchos boniatos naranjas; adapta la cocción si cambias de variedad. Contiene soja y sésamo; la salsa de soja habitual también lleva trigo. La nutrición cuenta los 25 g de aceite completos como estimación conservadora. Sirve recién hecho: las sobras refrigeradas, consumidas al día siguiente, pierden parte de la textura del glaseado.</p><h2>También puedes preparar</h2><ul><li><a href=\"/cerdo-repollo-vapor-seiro\">Cerdo y repollo al vapor en seiro con salsa de sésamo</a></li><li><a href=\"/mango-sago-coco\">Mango sago con coco: postre de mango y perlas de tapioca</a></li></ul>","content_html":"<p>Daigaku imo con boniato de piel morada, glaseado de azúcar y sésamo negro. Se ablanda al microondas y se dora en sartén, sin una olla de fritura profunda.</p><p>El satsumaimo japonés de pulpa amarilla es más firme que muchos boniatos naranjas; adapta la cocción si cambias de variedad. Contiene soja y sésamo; la salsa de soja habitual también lleva trigo. La nutrición cuenta los 25 g de aceite completos como estimación conservadora. Sirve recién hecho: las sobras refrigeradas, consumidas al día siguiente, pierden parte de la textura del glaseado.</p><h2>También puedes preparar</h2><ul><li><a href=\"/cerdo-repollo-vapor-seiro\">Cerdo y repollo al vapor en seiro con salsa de sésamo</a></li><li><a href=\"/mango-sago-coco\">Mango sago con coco: postre de mango y perlas de tapioca</a></li></ul>","ingredients":[{"name":"Boniato japonés de piel morada y pulpa amarilla","amount":"400","unit":"g"},{"name":"Aceite vegetal","amount":"25","unit":"g"},{"name":"Azúcar","amount":"50","unit":"g"},{"name":"Agua para el glaseado","amount":"30","unit":"ml"},{"name":"Salsa de soja","amount":"8","unit":"g"},{"name":"Semillas de sésamo negro","amount":"4","unit":"g"}],"steps":[{"title":"Corta el boniato","content":"Lava el boniato, quita los extremos y córtalo con piel en trozos irregulares de unos 3 cm. Procura tamaños parecidos para que se cocinen a la vez.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/daigaku-imo-boniato-caramelizado/paso-01.webp","image_alt":"Daigaku imo: boniato japonés caramelizado en sartén: Corta el boniato"},{"title":"Remoja y seca","content":"Remoja los trozos en agua fría 5 minutos. Escurre y seca muy bien con un paño o papel de cocina antes de continuar.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/daigaku-imo-boniato-caramelizado/paso-02.webp","image_alt":"Daigaku imo: boniato japonés caramelizado en sartén: Remoja y seca"},{"title":"Ablanda al microondas","content":"Pon el boniato en un bol apto para microondas con cubierta ventilada. Calienta a 600 W unos 5 minutos, hasta casi tierno. Prolonga por intervalos de 30 segundos si hace falta.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/daigaku-imo-boniato-caramelizado/paso-03.webp","image_alt":"Daigaku imo: boniato japonés caramelizado en sartén: Ablanda al microondas"},{"title":"Dora en sartén","content":"Calienta los 25 g de aceite a fuego medio. Cocina el boniato seco 8–10 minutos, girándolo para dorar varias caras. Retira a un plato.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/daigaku-imo-boniato-caramelizado/paso-04.webp","image_alt":"Daigaku imo: boniato japonés caramelizado en sartén: Dora en sartén"},{"title":"Prepara el glaseado","content":"Mezcla el azúcar, los 30 ml de agua y la salsa de soja en otra sartén limpia. Calienta 1–2 minutos, hasta formar un almíbar de burbujas grandes, sin quemarlo.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/daigaku-imo-boniato-caramelizado/paso-05.webp","image_alt":"Daigaku imo: boniato japonés caramelizado en sartén: Prepara el glaseado"},{"title":"Cubre los trozos","content":"Incorpora el boniato caliente y mezcla con cuidado unos 30 segundos. Retira del fuego cuando todos los trozos tengan una capa fina y brillante.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/daigaku-imo-boniato-caramelizado/paso-06.webp","image_alt":"Daigaku imo: boniato japonés caramelizado en sartén: Cubre los trozos"},{"title":"Añade el sésamo","content":"Espolvorea el sésamo negro y separa los trozos sobre papel de horno. Deja templar unos 5 minutos; el azúcar caliente puede quemar.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/daigaku-imo-boniato-caramelizado/paso-07.webp","image_alt":"Daigaku imo: boniato japonés caramelizado en sartén: Añade el sésamo"},{"title":"Sirve en pequeñas porciones","content":"Reparte entre cuatro personas y espera a que se pueda comer sin quemarse. Busca un centro tierno y un exterior brillante, con la piel morada visible.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/daigaku-imo-boniato-caramelizado/paso-08.webp","image_alt":"Daigaku imo: boniato japonés caramelizado en sartén: Sirve en pequeñas porciones"}],"category":"Postres","course":"Postres","cuisine":"Japonesa","difficulty":"Fácil","prep_time_minutes":10,"cook_time_minutes":20,"total_time_minutes":40,"servings":4,"image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/daigaku-imo-boniato-caramelizado/portada.webp","gallery":[{"url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/daigaku-imo-boniato-caramelizado/portada.webp","alt":"Daigaku imo: boniato japonés caramelizado en sartén"}],"video_urls":[],"keywords":["Daigaku imo: boniato japonés caramelizado en sartén","Boniato japonés de piel morada y pulpa amarilla","Aceite vegetal"],"nutrition":{"calories":196,"protein_g":1.9,"carbs_g":33.0,"fat_g":6.8,"saturated_fat_g":0.7,"fiber_g":3.1,"sugar_g":16.7,"sodium_mg":165.0,"estimated":true,"serving_size":"1 de 4 porciones","source":"USDA FoodData Central SR Legacy","source_url":"https://fdc.nal.usda.gov/download-datasets/","method":"Suma de referencias por peso, dividida entre las porciones; todos los ingredientes principales contabilizados.","note":"Estimación orientativa, no medición del plato cocinado. Las marcas y el escurrido cambian los valores; los nutrientes sin dato completo no se muestran. Referencias genéricas para mostaza preparada, crema, boniato, aceite y chocolate; las variedades y marcas concretas pueden diferir."},"seo":{"title":"Daigaku imo: boniato japonés caramelizado en sartén","description":"Daigaku imo con boniato de piel morada, glaseado de azúcar y sésamo negro. Se ablanda al microondas y se dora en sartén, sin una olla de fritura profunda.","image_alt":"Daigaku imo: boniato japonés caramelizado en sartén","image_variants":["https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/daigaku-imo-boniato-caramelizado/portada-1x1.webp","https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/daigaku-imo-boniato-caramelizado/portada-4x3.webp","https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/daigaku-imo-boniato-caramelizado/portada-16x9.webp"],"faq":[{"q":"¿Puedo usar boniato naranja?","a":"Sí, pero suele tener más humedad y romperse antes. Comprueba la cocción y manipúlalo con cuidado."},{"q":"¿Se hace en una olla de aceite?","a":"No. Esta versión usa microondas y dorado en sartén con una cantidad medida de aceite; no es la doble fritura tradicional."},{"q":"¿Por qué queda duro el caramelo?","a":"Puede haberse cocinado demasiado. Detén el almíbar cuando haga burbujas grandes y cubra los trozos, antes de que se vuelva oscuro."}],"rest_time_minutes":10},"published":false,"editorial_status":"draft","source_url":null,"source_post_id":null,"recipe_group_id":"938f01d5-5b22-4e76-9e2c-a2215f3cf548"},{"language":"de","slug":"daigaku-imo-kandierte-suesskartoffeln","public_path":"/de/daigaku-imo-kandierte-suesskartoffeln","title":"Daigaku Imo: japanische Süßkartoffeln mit Sesamglasur","excerpt":"Japanische Süßkartoffeln mit violetter Schale, glänzender Zucker-Soja-Glasur und schwarzem Sesam. Diese Variante kombiniert Mikrowelle und Pfanne statt Frittieren.","summary":"Japanische Süßkartoffeln mit violetter Schale, glänzender Zucker-Soja-Glasur und schwarzem Sesam. Diese Variante kombiniert Mikrowelle und Pfanne statt Frittieren.","notes":"<p>Enthält Soja, Sesam und durch übliche Sojasauce auch Weizen. Dies ist eine Mikrowellen-Pfannen-Variante statt des traditionellen zweifachen Frittierens. Die Schätzung berücksichtigt vorsichtshalber alle 25 g Öl. Gelbfleischige japanische Sorten bleiben stabiler als orange Sorten. Frisch essen; Reste innerhalb von 2 Stunden kühlen und in 1 Tag verbrauchen, wobei die Glasur weicher wird.</p><h2>Auch ausprobieren</h2><ul><li><a href=\"/de/seiro-schweinefleisch-kohl\">Schweinefleisch und Kohl aus dem Seiro mit Sesamsauce</a></li><li><a href=\"/de/mango-sago-kokos\">Mango-Sago mit Kokosmilch und Tapiokaperlen</a></li></ul>","content_html":"<p>Japanische Süßkartoffeln mit violetter Schale, glänzender Zucker-Soja-Glasur und schwarzem Sesam. Diese Variante kombiniert Mikrowelle und Pfanne statt Frittieren.</p><p>Enthält Soja, Sesam und durch übliche Sojasauce auch Weizen. Dies ist eine Mikrowellen-Pfannen-Variante statt des traditionellen zweifachen Frittierens. Die Schätzung berücksichtigt vorsichtshalber alle 25 g Öl. Gelbfleischige japanische Sorten bleiben stabiler als orange Sorten. Frisch essen; Reste innerhalb von 2 Stunden kühlen und in 1 Tag verbrauchen, wobei die Glasur weicher wird.</p><h2>Auch ausprobieren</h2><ul><li><a href=\"/de/seiro-schweinefleisch-kohl\">Schweinefleisch und Kohl aus dem Seiro mit Sesamsauce</a></li><li><a href=\"/de/mango-sago-kokos\">Mango-Sago mit Kokosmilch und Tapiokaperlen</a></li></ul>","ingredients":[{"name":"Japanische Süßkartoffeln mit Schale","amount":"400","unit":"g"},{"name":"Pflanzenöl","amount":"25","unit":"g"},{"name":"Zucker","amount":"50","unit":"g"},{"name":"Wasser","amount":"30","unit":"ml"},{"name":"Sojasauce","amount":"8","unit":"g"},{"name":"Schwarze Sesamsamen","amount":"4","unit":"g"}],"steps":[{"title":"Schneiden","content":"Süßkartoffeln gründlich waschen und schadhafte Stellen entfernen. Mit violetter Schale in unregelmäßige, etwa 3 cm große Stücke schneiden.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/daigaku-imo-boniato-caramelizado/paso-01.webp","image_alt":"Daigaku Imo: japanische Süßkartoffeln mit Sesamglasur: Schneiden"},{"title":"Wässern und trocknen","content":"5 Minuten in Wasser legen, abgießen und mit einem sauberen Tuch gründlich trocknen. Nasse Oberflächen verursachen Spritzer im heißen Öl.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/daigaku-imo-boniato-caramelizado/paso-02.webp","image_alt":"Daigaku Imo: japanische Süßkartoffeln mit Sesamglasur: Wässern und trocknen"},{"title":"Vorgaren","content":"In ein mikrowellengeeignetes Gefäß geben, mit belüftetem Deckel abdecken und bei 600 Watt etwa 5 Minuten garen. Mit einem Spieß prüfen und bei Bedarf in 30-Sekunden-Schritten weitergaren.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/daigaku-imo-boniato-caramelizado/paso-03.webp","image_alt":"Daigaku Imo: japanische Süßkartoffeln mit Sesamglasur: Vorgaren"},{"title":"In der Pfanne bräunen","content":"25 g Öl in einer großen Pfanne bei mittlerer Hitze erwärmen. Die trockenen, vorgegarten Stücke 8–10 Minuten vorsichtig wenden, bis mehrere Seiten goldbraun sind.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/daigaku-imo-boniato-caramelizado/paso-04.webp","image_alt":"Daigaku Imo: japanische Süßkartoffeln mit Sesamglasur: In der Pfanne bräunen"},{"title":"Glasur kochen","content":"Zucker, 30 ml Wasser und Sojasauce in einer separaten sauberen Pfanne 1–2 Minuten köcheln, bis große glänzende Blasen entstehen. Nicht zu dunklem, hartem Karamell einkochen.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/daigaku-imo-boniato-caramelizado/paso-05.webp","image_alt":"Daigaku Imo: japanische Süßkartoffeln mit Sesamglasur: Glasur kochen"},{"title":"Überziehen","content":"Warme Süßkartoffeln in die Glasur geben und bei kleiner Hitze etwa 30 Sekunden vorsichtig schwenken, bis sie glänzend überzogen sind. Stücke nicht zerdrücken.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/daigaku-imo-boniato-caramelizado/paso-06.webp","image_alt":"Daigaku Imo: japanische Süßkartoffeln mit Sesamglasur: Überziehen"},{"title":"Sesam und Abkühlen","content":"Schwarzen Sesam darüberstreuen und die Stücke getrennt auf Backpapier verteilen. 5 Minuten abkühlen lassen; die frische Zuckerglasur ist sehr heiß.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/daigaku-imo-boniato-caramelizado/paso-07.webp","image_alt":"Daigaku Imo: japanische Süßkartoffeln mit Sesamglasur: Sesam und Abkühlen"},{"title":"Servieren","content":"In vier Portionen aufteilen und erst essen, wenn die Glasur ausreichend abgekühlt ist. Heißen Sirup weder berühren noch probieren; frisch schmeckt die Hülle am besten.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/daigaku-imo-boniato-caramelizado/paso-08.webp","image_alt":"Daigaku Imo: japanische Süßkartoffeln mit Sesamglasur: Servieren"}],"category":"Desserts","course":"Desserts","cuisine":"Japanisch","difficulty":"Einfach","prep_time_minutes":10,"cook_time_minutes":20,"total_time_minutes":40,"servings":4,"image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/daigaku-imo-boniato-caramelizado/portada.webp","gallery":[{"url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/daigaku-imo-boniato-caramelizado/portada.webp","alt":"Daigaku Imo: japanische Süßkartoffeln mit Sesamglasur"}],"video_urls":[],"keywords":["Daigaku Imo: japanische Süßkartoffeln mit Sesamglasur","Japanische Süßkartoffeln mit Schale","Pflanzenöl"],"nutrition":{"calories":196,"protein_g":1.9,"carbs_g":33.0,"fat_g":6.8,"saturated_fat_g":0.7,"fiber_g":3.1,"sugar_g":16.7,"sodium_mg":165.0,"estimated":true,"serving_size":"1 von 4 Portionen","source":"USDA FoodData Central SR Legacy","source_url":"https://fdc.nal.usda.gov/download-datasets/","method":"Referenzwerte nach Zutatengewicht summiert und durch die Portionen geteilt.","note":"Ungefähre Schätzung, keine Messung des fertigen Gerichts. Marken und Abtropfen verändern die Werte; unvollständige Nährstoffdaten werden nicht angezeigt. Generische Referenzen für Senf, Sahne, Süßkartoffeln, Öl und Schokolade; Sorten und Marken können abweichen."},"seo":{"title":"Daigaku Imo: japanische Süßkartoffeln mit Sesamglasur","description":"Japanische Süßkartoffeln mit violetter Schale, glänzender Zucker-Soja-Glasur und schwarzem Sesam. Diese Variante kombiniert Mikrowelle und Pfanne statt Frittieren.","image_alt":"Daigaku Imo: japanische Süßkartoffeln mit Sesamglasur","image_variants":["https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/daigaku-imo-boniato-caramelizado/portada-1x1.webp","https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/daigaku-imo-boniato-caramelizado/portada-4x3.webp","https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/daigaku-imo-boniato-caramelizado/portada-16x9.webp"],"faq":[{"q":"Gehen orange Süßkartoffeln?","a":"Ja, aber sie sind weicher und können beim Glasieren zerfallen. Früher prüfen und besonders vorsichtig wenden."},{"q":"Warum wird die Hülle hart?","a":"Der Sirup wurde möglicherweise zu stark eingekocht. Bei großen Blasen und glänzendem Überzug stoppen, nicht dunkel karamellisieren."},{"q":"Geht es ohne Mikrowelle?","a":"Stücke knapp weich dämpfen und die Oberfläche vor dem Braten gut trocknen lassen. Gar- und Gesamtzeit ändern sich."}],"rest_time_minutes":10},"published":false,"editorial_status":"draft","source_url":null,"source_post_id":null,"recipe_group_id":"938f01d5-5b22-4e76-9e2c-a2215f3cf548"},{"language":"en","slug":"daigaku-imo-candied-japanese-sweet-potatoes","public_path":"/en/daigaku-imo-candied-japanese-sweet-potatoes","title":"Daigaku imo: candied Japanese sweet potatoes in a pan","excerpt":"Purple-skinned Japanese sweet potatoes with a glossy sugar-and-soy glaze and black sesame. This microwave-and-pan version uses less oil than deep frying.","summary":"Purple-skinned Japanese sweet potatoes with a glossy sugar-and-soy glaze and black sesame. This microwave-and-pan version uses less oil than deep frying.","notes":"<p>Contains soy, sesame and usually wheat from soy sauce. This version uses microwave cooking and pan browning, rather than traditional double deep frying. Nutrition conservatively counts all 25 g oil. Purple-skinned, yellow-fleshed Japanese sweet potatoes hold their shape well; orange varieties are more fragile. Best eaten fresh; refrigerate leftovers within 2 hours and use within 1 day, accepting a softer glaze.</p><h2>You may also like</h2><ul><li><a href=\"/en/seiro-steamed-pork-cabbage\">Seiro steamed pork and cabbage with sesame sauce</a></li><li><a href=\"/en/mango-sago-coconut\">Mango sago with coconut and tapioca pearls</a></li></ul>","content_html":"<p>Purple-skinned Japanese sweet potatoes with a glossy sugar-and-soy glaze and black sesame. This microwave-and-pan version uses less oil than deep frying.</p><p>Contains soy, sesame and usually wheat from soy sauce. This version uses microwave cooking and pan browning, rather than traditional double deep frying. Nutrition conservatively counts all 25 g oil. Purple-skinned, yellow-fleshed Japanese sweet potatoes hold their shape well; orange varieties are more fragile. Best eaten fresh; refrigerate leftovers within 2 hours and use within 1 day, accepting a softer glaze.</p><h2>You may also like</h2><ul><li><a href=\"/en/seiro-steamed-pork-cabbage\">Seiro steamed pork and cabbage with sesame sauce</a></li><li><a href=\"/en/mango-sago-coconut\">Mango sago with coconut and tapioca pearls</a></li></ul>","ingredients":[{"name":"Japanese sweet potato, skin on","amount":"400","unit":"g"},{"name":"Vegetable oil","amount":"25","unit":"g"},{"name":"Sugar","amount":"50","unit":"g"},{"name":"Water","amount":"30","unit":"ml"},{"name":"Soy sauce","amount":"8","unit":"g"},{"name":"Black sesame seeds","amount":"4","unit":"g"}],"steps":[{"title":"Cut the sweet potato","content":"Scrub the sweet potatoes and remove damaged areas. Cut into irregular pieces about 3 cm across, retaining the purple skin.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/daigaku-imo-boniato-caramelizado/paso-01.webp","image_alt":"Daigaku imo: candied Japanese sweet potatoes in a pan: Cut the sweet potato"},{"title":"Soak and dry","content":"Soak in water for 5 minutes, then drain and dry thoroughly with a clean cloth. Surface water causes splattering in hot oil.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/daigaku-imo-boniato-caramelizado/paso-02.webp","image_alt":"Daigaku imo: candied Japanese sweet potatoes in a pan: Soak and dry"},{"title":"Microwave","content":"Place in a microwave-safe dish, cover with a vented lid and cook at 600 W for about 5 minutes. Check with a skewer; continue in 30-second intervals until just tender.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/daigaku-imo-boniato-caramelizado/paso-03.webp","image_alt":"Daigaku imo: candied Japanese sweet potatoes in a pan: Microwave"},{"title":"Brown in the pan","content":"Heat 25 g oil in a wide pan over medium heat. Add the dried, precooked pieces and cook for 8–10 minutes, turning gently until several sides are golden.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/daigaku-imo-boniato-caramelizado/paso-04.webp","image_alt":"Daigaku imo: candied Japanese sweet potatoes in a pan: Brown in the pan"},{"title":"Prepare the glaze","content":"In a separate clean pan, heat the sugar, 30 ml water and soy sauce. Simmer for 1–2 minutes until large glossy bubbles form; do not reduce to a dark, hard caramel.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/daigaku-imo-boniato-caramelizado/paso-05.webp","image_alt":"Daigaku imo: candied Japanese sweet potatoes in a pan: Prepare the glaze"},{"title":"Coat","content":"Add the warm sweet potatoes to the glaze and toss gently over low heat for about 30 seconds, until glossy and coated. Keep pieces intact.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/daigaku-imo-boniato-caramelizado/paso-06.webp","image_alt":"Daigaku imo: candied Japanese sweet potatoes in a pan: Coat"},{"title":"Add sesame and cool","content":"Sprinkle with black sesame and spread on baking parchment, separating the pieces. Cool for 5 minutes; the sugar glaze is extremely hot straight from the pan.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/daigaku-imo-boniato-caramelizado/paso-07.webp","image_alt":"Daigaku imo: candied Japanese sweet potatoes in a pan: Add sesame and cool"},{"title":"Serve","content":"Divide into four portions and serve once the glaze is safe to eat. The coating is best freshly made; avoid touching or tasting hot syrup.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/daigaku-imo-boniato-caramelizado/paso-08.webp","image_alt":"Daigaku imo: candied Japanese sweet potatoes in a pan: Serve"}],"category":"Desserts","course":"Desserts","cuisine":"Japanese","difficulty":"Easy","prep_time_minutes":10,"cook_time_minutes":20,"total_time_minutes":40,"servings":4,"image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/daigaku-imo-boniato-caramelizado/portada.webp","gallery":[{"url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/daigaku-imo-boniato-caramelizado/portada.webp","alt":"Daigaku imo: candied Japanese sweet potatoes in a pan"}],"video_urls":[],"keywords":["Daigaku imo: candied Japanese sweet potatoes in a pan","Japanese sweet potato, skin on","Vegetable oil"],"nutrition":{"calories":196,"protein_g":1.9,"carbs_g":33.0,"fat_g":6.8,"saturated_fat_g":0.7,"fiber_g":3.1,"sugar_g":16.7,"sodium_mg":165.0,"estimated":true,"serving_size":"1 of 4 servings","source":"USDA FoodData Central SR Legacy","source_url":"https://fdc.nal.usda.gov/download-datasets/","method":"Reference nutrients summed by ingredient weight and divided by servings.","note":"Approximate estimate, not a measurement of the cooked dish. Brands and draining change values; nutrients with incomplete data are omitted. Generic references for prepared mustard, cream, sweet potato, oil and chocolate; specific varieties and brands can differ."},"seo":{"title":"Daigaku imo: candied Japanese sweet potatoes in a pan","description":"Purple-skinned Japanese sweet potatoes with a glossy sugar-and-soy glaze and black sesame. This microwave-and-pan version uses less oil than deep frying.","image_alt":"Daigaku imo: candied Japanese sweet potatoes in a pan","image_variants":["https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/daigaku-imo-boniato-caramelizado/portada-1x1.webp","https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/daigaku-imo-boniato-caramelizado/portada-4x3.webp","https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/daigaku-imo-boniato-caramelizado/portada-16x9.webp"],"faq":[{"q":"Can I use orange sweet potatoes?","a":"Yes, but they are softer and may break when coated. Check microwave doneness earlier and turn gently."},{"q":"Why is the coating hard?","a":"The syrup may have reduced too far. Stop at large bubbles and a glossy coating; do not cook it to a dark caramel."},{"q":"Can I make it without a microwave?","a":"Steam the pieces until just tender, then let the surface dry thoroughly before pan browning. Cooking and total times will change."}],"rest_time_minutes":10},"published":false,"editorial_status":"draft","source_url":null,"source_post_id":null,"recipe_group_id":"938f01d5-5b22-4e76-9e2c-a2215f3cf548"},{"language":"fr","slug":"daigaku-imo-patates-douces-caramelisees","public_path":"/fr/daigaku-imo-patates-douces-caramelisees","title":"Daigaku imo : patates douces japonaises glacées à la poêle","excerpt":"Des patates douces japonaises à peau violette, nappées d’un glaçage sucre-soja et de sésame noir. Cette version associe micro-ondes et poêle sans bain de friture.","summary":"Des patates douces japonaises à peau violette, nappées d’un glaçage sucre-soja et de sésame noir. Cette version associe micro-ondes et poêle sans bain de friture.","notes":"<p>Contient soja, sésame et généralement blé via la sauce soja. Cette version micro-ondes et poêle diffère de la double friture traditionnelle. La nutrition compte par prudence les 25 g d’huile entiers. Les variétés japonaises à chair jaune tiennent mieux que celles à chair orange. À manger frais ; réfrigérez les restes avant 2 heures et consommez sous 1 jour, avec un glaçage plus mou.</p><h2>À préparer aussi</h2><ul><li><a href=\"/fr/porc-chou-vapeur-seiro\">Porc et chou vapeur en seiro, sauce au sésame</a></li><li><a href=\"/fr/mango-sago-noix-de-coco\">Mango sago : dessert à la mangue, coco et tapioca</a></li></ul>","content_html":"<p>Des patates douces japonaises à peau violette, nappées d’un glaçage sucre-soja et de sésame noir. Cette version associe micro-ondes et poêle sans bain de friture.</p><p>Contient soja, sésame et généralement blé via la sauce soja. Cette version micro-ondes et poêle diffère de la double friture traditionnelle. La nutrition compte par prudence les 25 g d’huile entiers. Les variétés japonaises à chair jaune tiennent mieux que celles à chair orange. À manger frais ; réfrigérez les restes avant 2 heures et consommez sous 1 jour, avec un glaçage plus mou.</p><h2>À préparer aussi</h2><ul><li><a href=\"/fr/porc-chou-vapeur-seiro\">Porc et chou vapeur en seiro, sauce au sésame</a></li><li><a href=\"/fr/mango-sago-noix-de-coco\">Mango sago : dessert à la mangue, coco et tapioca</a></li></ul>","ingredients":[{"name":"Patates douces japonaises avec peau","amount":"400","unit":"g"},{"name":"Huile végétale","amount":"25","unit":"g"},{"name":"Sucre","amount":"50","unit":"g"},{"name":"Eau","amount":"30","unit":"ml"},{"name":"Sauce soja","amount":"8","unit":"g"},{"name":"Graines de sésame noir","amount":"4","unit":"g"}],"steps":[{"title":"Découper","content":"Brossez les patates douces et retirez les parties abîmées. Gardez la peau violette et coupez en morceaux irréguliers d’environ 3 cm.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/daigaku-imo-boniato-caramelizado/paso-01.webp","image_alt":"Daigaku imo : patates douces japonaises glacées à la poêle: Découper"},{"title":"Tremper et sécher","content":"Faites tremper 5 minutes dans l’eau. Égouttez et séchez très soigneusement avec un linge propre pour éviter les projections dans l’huile.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/daigaku-imo-boniato-caramelizado/paso-02.webp","image_alt":"Daigaku imo : patates douces japonaises glacées à la poêle: Tremper et sécher"},{"title":"Précuire au micro-ondes","content":"Placez dans un plat adapté, couvrez d’un couvercle laissant échapper la vapeur et cuisez environ 5 minutes à 600 W. Vérifiez avec une pique ; prolongez par tranches de 30 secondes si nécessaire.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/daigaku-imo-boniato-caramelizado/paso-03.webp","image_alt":"Daigaku imo : patates douces japonaises glacées à la poêle: Précuire au micro-ondes"},{"title":"Dorer à la poêle","content":"Chauffez 25 g d’huile dans une grande poêle à feu moyen. Faites dorer les morceaux précuits et secs pendant 8–10 minutes, en les retournant délicatement.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/daigaku-imo-boniato-caramelizado/paso-04.webp","image_alt":"Daigaku imo : patates douces japonaises glacées à la poêle: Dorer à la poêle"},{"title":"Préparer le glaçage","content":"Dans une autre poêle propre, chauffez sucre, 30 ml d’eau et sauce soja. Laissez frémir 1–2 minutes jusqu’à de grosses bulles brillantes, sans faire un caramel sombre et dur.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/daigaku-imo-boniato-caramelizado/paso-05.webp","image_alt":"Daigaku imo : patates douces japonaises glacées à la poêle: Préparer le glaçage"},{"title":"Enrober","content":"Ajoutez les patates douces chaudes au glaçage. Mélangez délicatement environ 30 secondes à feu doux pour les napper sans les écraser.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/daigaku-imo-boniato-caramelizado/paso-06.webp","image_alt":"Daigaku imo : patates douces japonaises glacées à la poêle: Enrober"},{"title":"Ajouter le sésame","content":"Parsemez de sésame noir et étalez sur du papier cuisson en séparant les morceaux. Laissez refroidir 5 minutes : le glaçage sucré est brûlant à la sortie de la poêle.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/daigaku-imo-boniato-caramelizado/paso-07.webp","image_alt":"Daigaku imo : patates douces japonaises glacées à la poêle: Ajouter le sésame"},{"title":"Servir","content":"Répartissez en quatre portions et servez lorsque le glaçage peut être mangé sans brûlure. Ne touchez ni ne goûtez le sirop chaud ; la texture est meilleure fraîche.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/daigaku-imo-boniato-caramelizado/paso-08.webp","image_alt":"Daigaku imo : patates douces japonaises glacées à la poêle: Servir"}],"category":"Desserts","course":"Desserts","cuisine":"Japonaise","difficulty":"Facile","prep_time_minutes":10,"cook_time_minutes":20,"total_time_minutes":40,"servings":4,"image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/daigaku-imo-boniato-caramelizado/portada.webp","gallery":[{"url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/daigaku-imo-boniato-caramelizado/portada.webp","alt":"Daigaku imo : patates douces japonaises glacées à la poêle"}],"video_urls":[],"keywords":["Daigaku imo : patates douces japonaises glacées à la poêle","Patates douces japonaises avec peau","Huile végétale"],"nutrition":{"calories":196,"protein_g":1.9,"carbs_g":33.0,"fat_g":6.8,"saturated_fat_g":0.7,"fiber_g":3.1,"sugar_g":16.7,"sodium_mg":165.0,"estimated":true,"serving_size":"1 des 4 portions","source":"USDA FoodData Central SR Legacy","source_url":"https://fdc.nal.usda.gov/download-datasets/","method":"Somme des références selon le poids des ingrédients, divisée par le nombre de portions.","note":"Estimation indicative, pas une mesure du plat cuisiné. Marques et égouttage changent les valeurs ; les nutriments incomplets ne sont pas affichés. Références génériques pour moutarde préparée, crème, patate douce, huile et chocolat ; variétés et marques peuvent différer."},"seo":{"title":"Daigaku imo : patates douces japonaises glacées à la poêle","description":"Des patates douces japonaises à peau violette, nappées d’un glaçage sucre-soja et de sésame noir. Cette version associe micro-ondes et poêle sans bain de friture.","image_alt":"Daigaku imo : patates douces japonaises glacées à la poêle","image_variants":["https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/daigaku-imo-boniato-caramelizado/portada-1x1.webp","https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/daigaku-imo-boniato-caramelizado/portada-4x3.webp","https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/daigaku-imo-boniato-caramelizado/portada-16x9.webp"],"faq":[{"q":"Peut-on utiliser une patate douce orange ?","a":"Oui, mais elle est plus fragile et peut se casser pendant l’enrobage. Vérifiez plus tôt la cuisson et manipulez doucement."},{"q":"Pourquoi le glaçage durcit-il ?","a":"Le sirop a probablement trop réduit. Arrêtez aux grosses bulles et au nappage brillant, sans caramélisation foncée."},{"q":"Comment faire sans micro-ondes ?","a":"Cuisez les morceaux à la vapeur jusqu’à ce qu’ils soient juste tendres, puis séchez bien leur surface avant de les dorer. Les temps changent."}],"rest_time_minutes":10},"published":false,"editorial_status":"draft","source_url":null,"source_post_id":null,"recipe_group_id":"938f01d5-5b22-4e76-9e2c-a2215f3cf548"},{"language":"it","slug":"daigaku-imo-patate-dolci-caramellate","public_path":"/it/daigaku-imo-patate-dolci-caramellate","title":"Daigaku imo: patate dolci giapponesi glassate in padella","excerpt":"Patate dolci giapponesi con buccia viola, glassa lucida di zucchero e soia e sesamo nero. Questa versione combina microonde e padella senza frittura a immersione.","summary":"Patate dolci giapponesi con buccia viola, glassa lucida di zucchero e soia e sesamo nero. Questa versione combina microonde e padella senza frittura a immersione.","notes":"<p>Contiene soia, sesamo e solitamente frumento dalla salsa di soia. Questa variante usa microonde e padella invece della tradizionale doppia frittura. La nutrizione conta prudentemente tutti i 25 g d’olio. Le varietà giapponesi a polpa gialla tengono meglio di quelle arancioni. Consuma fresco; riponi gli avanzi in frigorifero entro 2 ore e consumali entro 1 giorno, con glassa più morbida.</p><h2>Da provare anche</h2><ul><li><a href=\"/it/maiale-cavolo-vapore-seiro\">Maiale e cavolo al vapore nel seiro con salsa al sesamo</a></li><li><a href=\"/it/mango-sago-cocco\">Mango sago al cocco con perle di tapioca</a></li></ul>","content_html":"<p>Patate dolci giapponesi con buccia viola, glassa lucida di zucchero e soia e sesamo nero. Questa versione combina microonde e padella senza frittura a immersione.</p><p>Contiene soia, sesamo e solitamente frumento dalla salsa di soia. Questa variante usa microonde e padella invece della tradizionale doppia frittura. La nutrizione conta prudentemente tutti i 25 g d’olio. Le varietà giapponesi a polpa gialla tengono meglio di quelle arancioni. Consuma fresco; riponi gli avanzi in frigorifero entro 2 ore e consumali entro 1 giorno, con glassa più morbida.</p><h2>Da provare anche</h2><ul><li><a href=\"/it/maiale-cavolo-vapore-seiro\">Maiale e cavolo al vapore nel seiro con salsa al sesamo</a></li><li><a href=\"/it/mango-sago-cocco\">Mango sago al cocco con perle di tapioca</a></li></ul>","ingredients":[{"name":"Patate dolci giapponesi con buccia","amount":"400","unit":"g"},{"name":"Olio vegetale","amount":"25","unit":"g"},{"name":"Zucchero","amount":"50","unit":"g"},{"name":"Acqua","amount":"30","unit":"ml"},{"name":"Salsa di soia","amount":"8","unit":"g"},{"name":"Semi di sesamo nero","amount":"4","unit":"g"}],"steps":[{"title":"Taglia","content":"Lava bene le patate dolci ed elimina le parti rovinate. Mantieni la buccia viola e taglia a pezzi irregolari di circa 3 cm.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/daigaku-imo-boniato-caramelizado/paso-01.webp","image_alt":"Daigaku imo: patate dolci giapponesi glassate in padella: Taglia"},{"title":"Ammolla e asciuga","content":"Lascia in acqua per 5 minuti, scola e asciuga accuratamente con un panno pulito. L’acqua superficiale provoca schizzi nell’olio caldo.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/daigaku-imo-boniato-caramelizado/paso-02.webp","image_alt":"Daigaku imo: patate dolci giapponesi glassate in padella: Ammolla e asciuga"},{"title":"Precuoci al microonde","content":"Metti in un recipiente adatto, copri con un coperchio sfiatato e cuoci a 600 W per circa 5 minuti. Controlla con uno stecchino e prolunga a intervalli di 30 secondi se serve.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/daigaku-imo-boniato-caramelizado/paso-03.webp","image_alt":"Daigaku imo: patate dolci giapponesi glassate in padella: Precuoci al microonde"},{"title":"Rosola","content":"Scalda 25 g d’olio in una padella ampia a fuoco medio. Rosola i pezzi precotti e asciutti per 8–10 minuti, girandoli delicatamente per dorare più lati.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/daigaku-imo-boniato-caramelizado/paso-04.webp","image_alt":"Daigaku imo: patate dolci giapponesi glassate in padella: Rosola"},{"title":"Prepara la glassa","content":"In un’altra padella pulita scalda zucchero, 30 ml d’acqua e salsa di soia. Fai sobbollire 1–2 minuti, fino a bolle grandi e lucide, senza arrivare a un caramello scuro e duro.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/daigaku-imo-boniato-caramelizado/paso-05.webp","image_alt":"Daigaku imo: patate dolci giapponesi glassate in padella: Prepara la glassa"},{"title":"Glassa","content":"Unisci le patate dolci calde e mescola delicatamente a fuoco basso per circa 30 secondi, rivestendole senza romperle.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/daigaku-imo-boniato-caramelizado/paso-06.webp","image_alt":"Daigaku imo: patate dolci giapponesi glassate in padella: Glassa"},{"title":"Aggiungi sesamo e raffredda","content":"Cospargi di sesamo nero e separa i pezzi su carta da forno. Lascia raffreddare 5 minuti: la glassa appena cotta è molto calda.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/daigaku-imo-boniato-caramelizado/paso-07.webp","image_alt":"Daigaku imo: patate dolci giapponesi glassate in padella: Aggiungi sesamo e raffredda"},{"title":"Servi","content":"Dividi in quattro porzioni e servi quando la glassa non rischia di scottare. Non toccare né assaggiare lo sciroppo bollente; la copertura è migliore appena fatta.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/daigaku-imo-boniato-caramelizado/paso-08.webp","image_alt":"Daigaku imo: patate dolci giapponesi glassate in padella: Servi"}],"category":"Dolci","course":"Dolci","cuisine":"Giapponese","difficulty":"Facile","prep_time_minutes":10,"cook_time_minutes":20,"total_time_minutes":40,"servings":4,"image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/daigaku-imo-boniato-caramelizado/portada.webp","gallery":[{"url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/daigaku-imo-boniato-caramelizado/portada.webp","alt":"Daigaku imo: patate dolci giapponesi glassate in padella"}],"video_urls":[],"keywords":["Daigaku imo: patate dolci giapponesi glassate in padella","Patate dolci giapponesi con buccia","Olio vegetale"],"nutrition":{"calories":196,"protein_g":1.9,"carbs_g":33.0,"fat_g":6.8,"saturated_fat_g":0.7,"fiber_g":3.1,"sugar_g":16.7,"sodium_mg":165.0,"estimated":true,"serving_size":"1 di 4 porzioni","source":"USDA FoodData Central SR Legacy","source_url":"https://fdc.nal.usda.gov/download-datasets/","method":"Somma dei valori di riferimento per peso, divisa per le porzioni.","note":"Stima indicativa, non misurazione del piatto cotto. Marche e scolatura modificano i valori; nutrienti con dati incompleti non sono mostrati. Riferimenti generici per senape preparata, panna, patata dolce, olio e cioccolato; varietà e marche possono differire."},"seo":{"title":"Daigaku imo: patate dolci giapponesi glassate in padella","description":"Patate dolci giapponesi con buccia viola, glassa lucida di zucchero e soia e sesamo nero. Questa versione combina microonde e padella senza frittura a immersione.","image_alt":"Daigaku imo: patate dolci giapponesi glassate in padella","image_variants":["https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/daigaku-imo-boniato-caramelizado/portada-1x1.webp","https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/daigaku-imo-boniato-caramelizado/portada-4x3.webp","https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/daigaku-imo-boniato-caramelizado/portada-16x9.webp"],"faq":[{"q":"Posso usare patate dolci arancioni?","a":"Sì, ma sono più fragili e possono rompersi durante la glassatura. Controlla prima la cottura e girale con cautela."},{"q":"Perché la glassa diventa dura?","a":"Lo sciroppo potrebbe essersi ridotto troppo. Fermati alle bolle grandi e al rivestimento lucido, senza caramellare scuro."},{"q":"Si può fare senza microonde?","a":"Cuoci i pezzi a vapore finché appena teneri, poi asciuga bene la superficie prima di rosolarli. I tempi cambiano."}],"rest_time_minutes":10},"published":false,"editorial_status":"draft","source_url":null,"source_post_id":null,"recipe_group_id":"938f01d5-5b22-4e76-9e2c-a2215f3cf548"},{"language":"ja","slug":"daigaku-imo-frying-pan-microwave","public_path":"/ja/daigaku-imo-frying-pan-microwave","title":"大学いも：電子レンジとフライパンで作る黒ごま風味","excerpt":"皮付きさつまいもを電子レンジで下加熱し、フライパンで焼いて砂糖としょうゆのたれを絡めます。揚げずに作る、黒ごま入り大学いも4人分です。","summary":"皮付きさつまいもを電子レンジで下加熱し、フライパンで焼いて砂糖としょうゆのたれを絡めます。揚げずに作る、黒ごま入り大学いも4人分です。","notes":"<p>大豆、ごま、通常のしょうゆに由来する小麦を含みます。伝統的な二度揚げとは異なる、電子レンジとフライパンを使う方法です。栄養値は油25 gをすべて食べた想定です。黄色い果肉の日本のさつまいもは形を保ちやすく、オレンジ色の品種は崩れやすくなります。作りたてがおすすめです。残りは2時間以内に冷蔵し、たれが柔らかくなることを了承のうえ1日以内に食べます。</p><h2>こちらのレシピも</h2><ul><li><a href=\"/ja/buta-cabbage-seiro-mushi\">豚肉とキャベツのせいろ蒸し、ごまだれ添え</a></li><li><a href=\"/ja/mango-sago-coconut\">マンゴーサゴ：ココナッツと小粒タピオカのデザート</a></li></ul>","content_html":"<p>皮付きさつまいもを電子レンジで下加熱し、フライパンで焼いて砂糖としょうゆのたれを絡めます。揚げずに作る、黒ごま入り大学いも4人分です。</p><p>大豆、ごま、通常のしょうゆに由来する小麦を含みます。伝統的な二度揚げとは異なる、電子レンジとフライパンを使う方法です。栄養値は油25 gをすべて食べた想定です。黄色い果肉の日本のさつまいもは形を保ちやすく、オレンジ色の品種は崩れやすくなります。作りたてがおすすめです。残りは2時間以内に冷蔵し、たれが柔らかくなることを了承のうえ1日以内に食べます。</p><h2>こちらのレシピも</h2><ul><li><a href=\"/ja/buta-cabbage-seiro-mushi\">豚肉とキャベツのせいろ蒸し、ごまだれ添え</a></li><li><a href=\"/ja/mango-sago-coconut\">マンゴーサゴ：ココナッツと小粒タピオカのデザート</a></li></ul>","ingredients":[{"name":"さつまいも（皮付き）","amount":"400","unit":"g"},{"name":"植物油","amount":"25","unit":"g"},{"name":"砂糖","amount":"50","unit":"g"},{"name":"水","amount":"30","unit":"ml"},{"name":"しょうゆ","amount":"8","unit":"g"},{"name":"黒ごま","amount":"4","unit":"g"}],"steps":[{"title":"さつまいもを切る","content":"さつまいもをよく洗い、傷んだ部分を除きます。紫色の皮を残し、約3 cmの乱切りにします。","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/daigaku-imo-boniato-caramelizado/paso-01.webp","image_alt":"大学いも：電子レンジとフライパンで作る黒ごま風味: さつまいもを切る"},{"title":"水にさらして乾かす","content":"5分水にさらして水を切り、清潔な布で十分に拭きます。表面の水分は熱い油のはねる原因になります。","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/daigaku-imo-boniato-caramelizado/paso-02.webp","image_alt":"大学いも：電子レンジとフライパンで作る黒ごま風味: 水にさらして乾かす"},{"title":"電子レンジで加熱","content":"耐熱容器に入れ、蒸気が抜けるふたをして600 Wで約5分加熱します。竹串で確かめ、必要なら30秒ずつ追加して、やっと柔らかい程度にします。","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/daigaku-imo-boniato-caramelizado/paso-03.webp","image_alt":"大学いも：電子レンジとフライパンで作る黒ごま風味: 電子レンジで加熱"},{"title":"フライパンで焼く","content":"大きなフライパンに油25 gを中火で熱します。下加熱して表面を乾かしたさつまいもを8〜10分、優しく返しながら数面がきつね色になるまで焼きます。","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/daigaku-imo-boniato-caramelizado/paso-04.webp","image_alt":"大学いも：電子レンジとフライパンで作る黒ごま風味: フライパンで焼く"},{"title":"たれを煮る","content":"別の清潔なフライパンに砂糖、水30 ml、しょうゆを入れます。1〜2分穏やかに煮て、大きくつやのある泡が出たら止め、濃い硬いカラメルにはしません。","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/daigaku-imo-boniato-caramelizado/paso-05.webp","image_alt":"大学いも：電子レンジとフライパンで作る黒ごま風味: たれを煮る"},{"title":"たれを絡める","content":"温かいさつまいもをたれに加え、弱火で約30秒優しく混ぜます。形を崩さず、表面につやが出るように絡めます。","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/daigaku-imo-boniato-caramelizado/paso-06.webp","image_alt":"大学いも：電子レンジとフライパンで作る黒ごま風味: たれを絡める"},{"title":"黒ごまを振って冷ます","content":"黒ごまを振り、オーブンペーパーに重ならないよう広げます。5分冷まします。できたての砂糖だれは非常に熱いので注意してください。","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/daigaku-imo-boniato-caramelizado/paso-07.webp","image_alt":"大学いも：電子レンジとフライパンで作る黒ごま風味: 黒ごまを振って冷ます"},{"title":"盛り付ける","content":"4人分に分け、たれが安全に食べられる温度になってから出します。熱いたれに触れたり味見したりせず、できたての食感を楽しみます。","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/daigaku-imo-boniato-caramelizado/paso-08.webp","image_alt":"大学いも：電子レンジとフライパンで作る黒ごま風味: 盛り付ける"}],"category":"デザート","course":"デザート","cuisine":"日本料理","difficulty":"簡単","prep_time_minutes":10,"cook_time_minutes":20,"total_time_minutes":40,"servings":4,"image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/daigaku-imo-boniato-caramelizado/portada.webp","gallery":[{"url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/daigaku-imo-boniato-caramelizado/portada.webp","alt":"大学いも：電子レンジとフライパンで作る黒ごま風味"}],"video_urls":[],"keywords":["大学いも：電子レンジとフライパンで作る黒ごま風味","さつまいも（皮付き）","植物油"],"nutrition":{"calories":196,"protein_g":1.9,"carbs_g":33.0,"fat_g":6.8,"saturated_fat_g":0.7,"fiber_g":3.1,"sugar_g":16.7,"sodium_mg":165.0,"estimated":true,"serving_size":"全4人分のうち1人分","source":"USDA FoodData Central SR Legacy","source_url":"https://fdc.nal.usda.gov/download-datasets/","method":"材料の重量に応じた参考栄養値を合計し、人数で割っています。","note":"調理済み料理の実測値ではなく概算です。商品や水切りで変わり、資料がそろわない栄養素は表示しません。 マスタード、生クリーム、さつまいも、油、チョコレートは一般的な参考値を使用し、品種や商品で異なります。"},"seo":{"title":"大学いも：電子レンジとフライパンで作る黒ごま風味","description":"皮付きさつまいもを電子レンジで下加熱し、フライパンで焼いて砂糖としょうゆのたれを絡めます。揚げずに作る、黒ごま入り大学いも4人分です。","image_alt":"大学いも：電子レンジとフライパンで作る黒ごま風味","image_variants":["https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/daigaku-imo-boniato-caramelizado/portada-1x1.webp","https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/daigaku-imo-boniato-caramelizado/portada-4x3.webp","https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/daigaku-imo-boniato-caramelizado/portada-16x9.webp"],"faq":[{"q":"オレンジ色のさつまいもでも作れますか？","a":"使えますが柔らかく、たれを絡める際に崩れやすくなります。早めに加熱状態を確かめ、優しく返してください。"},{"q":"たれが硬くなるのはなぜ？","a":"煮詰めすぎの可能性があります。大きな泡とつやのある状態で止め、濃いカラメルにしないでください。"},{"q":"電子レンジなしで作れますか？","a":"やっと柔らかくなるまで蒸し、表面をよく乾かしてから焼きます。加熱時間と総時間は変わります。"}],"rest_time_minutes":10},"published":false,"editorial_status":"draft","source_url":null,"source_post_id":null,"recipe_group_id":"938f01d5-5b22-4e76-9e2c-a2215f3cf548"},{"language":"pt","slug":"daigaku-imo-batata-doce-caramelizada","public_path":"/pt/daigaku-imo-batata-doce-caramelizada","title":"Daigaku imo: batata-doce japonesa caramelizada na frigideira","excerpt":"Batata-doce japonesa de casca roxa com calda brilhante de açúcar e shoyu e gergelim preto. Esta versão combina micro-ondas e frigideira, sem fritura por imersão.","summary":"Batata-doce japonesa de casca roxa com calda brilhante de açúcar e shoyu e gergelim preto. Esta versão combina micro-ondas e frigideira, sem fritura por imersão.","notes":"<p>Contém soja, gergelim e normalmente trigo do shoyu. Esta variante usa micro-ondas e frigideira em vez da tradicional fritura dupla. A nutrição conta, por prudência, todos os 25 g de óleo. A variedade japonesa de polpa amarela mantém melhor a forma; a alaranjada é mais frágil. Prefira consumir na hora; refrigere antes de 2 horas e consuma em até 1 dia, aceitando uma cobertura mais mole.</p><h2>Prepare também</h2><ul><li><a href=\"/pt/porco-repolho-vapor-seiro\">Porco e repolho no vapor em seiro com molho de gergelim</a></li><li><a href=\"/pt/mango-sago-coco\">Mango sago: sobremesa de manga, coco e tapioca</a></li></ul>","content_html":"<p>Batata-doce japonesa de casca roxa com calda brilhante de açúcar e shoyu e gergelim preto. Esta versão combina micro-ondas e frigideira, sem fritura por imersão.</p><p>Contém soja, gergelim e normalmente trigo do shoyu. Esta variante usa micro-ondas e frigideira em vez da tradicional fritura dupla. A nutrição conta, por prudência, todos os 25 g de óleo. A variedade japonesa de polpa amarela mantém melhor a forma; a alaranjada é mais frágil. Prefira consumir na hora; refrigere antes de 2 horas e consuma em até 1 dia, aceitando uma cobertura mais mole.</p><h2>Prepare também</h2><ul><li><a href=\"/pt/porco-repolho-vapor-seiro\">Porco e repolho no vapor em seiro com molho de gergelim</a></li><li><a href=\"/pt/mango-sago-coco\">Mango sago: sobremesa de manga, coco e tapioca</a></li></ul>","ingredients":[{"name":"Batata-doce japonesa com casca","amount":"400","unit":"g"},{"name":"Óleo vegetal","amount":"25","unit":"g"},{"name":"Açúcar","amount":"50","unit":"g"},{"name":"Água","amount":"30","unit":"ml"},{"name":"Molho de soja (shoyu)","amount":"8","unit":"g"},{"name":"Gergelim preto","amount":"4","unit":"g"}],"steps":[{"title":"Corte","content":"Escove as batatas-doces e retire partes danificadas. Mantenha a casca roxa e corte em pedaços irregulares de cerca de 3 cm.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/daigaku-imo-boniato-caramelizado/paso-01.webp","image_alt":"Daigaku imo: batata-doce japonesa caramelizada na frigideira: Corte"},{"title":"Deixe de molho e seque","content":"Deixe na água por 5 minutos. Escorra e seque muito bem com pano limpo; água na superfície causa respingos no óleo quente.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/daigaku-imo-boniato-caramelizado/paso-02.webp","image_alt":"Daigaku imo: batata-doce japonesa caramelizada na frigideira: Deixe de molho e seque"},{"title":"Pré-cozinhe no micro-ondas","content":"Coloque num recipiente próprio, cubra com tampa com saída de vapor e aqueça a 600 W por cerca de 5 minutos. Confira com um espeto e prolongue em intervalos de 30 segundos se necessário.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/daigaku-imo-boniato-caramelizado/paso-03.webp","image_alt":"Daigaku imo: batata-doce japonesa caramelizada na frigideira: Pré-cozinhe no micro-ondas"},{"title":"Doure na frigideira","content":"Aqueça 25 g de óleo numa frigideira grande em fogo médio. Doure os pedaços pré-cozidos e secos por 8–10 minutos, virando delicadamente para colorir vários lados.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/daigaku-imo-boniato-caramelizado/paso-04.webp","image_alt":"Daigaku imo: batata-doce japonesa caramelizada na frigideira: Doure na frigideira"},{"title":"Faça a calda","content":"Em outra frigideira limpa, aqueça açúcar, 30 ml de água e shoyu. Ferva suavemente por 1–2 minutos até formar bolhas grandes e brilhantes, sem virar caramelo escuro e duro.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/daigaku-imo-boniato-caramelizado/paso-05.webp","image_alt":"Daigaku imo: batata-doce japonesa caramelizada na frigideira: Faça a calda"},{"title":"Envolva","content":"Junte a batata-doce quente à calda e misture delicadamente em fogo baixo por cerca de 30 segundos, cobrindo os pedaços sem quebrá-los.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/daigaku-imo-boniato-caramelizado/paso-06.webp","image_alt":"Daigaku imo: batata-doce japonesa caramelizada na frigideira: Envolva"},{"title":"Finalize e esfrie","content":"Polvilhe gergelim preto e espalhe sobre papel-manteiga, separando os pedaços. Deixe esfriar 5 minutos; a calda recém-feita fica muito quente.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/daigaku-imo-boniato-caramelizado/paso-07.webp","image_alt":"Daigaku imo: batata-doce japonesa caramelizada na frigideira: Finalize e esfrie"},{"title":"Sirva","content":"Divida em quatro porções e sirva quando a cobertura não oferecer risco de queimadura. Não toque nem prove a calda quente; a textura é melhor na hora.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/daigaku-imo-boniato-caramelizado/paso-08.webp","image_alt":"Daigaku imo: batata-doce japonesa caramelizada na frigideira: Sirva"}],"category":"Sobremesas","course":"Sobremesas","cuisine":"Japonesa","difficulty":"Fácil","prep_time_minutes":10,"cook_time_minutes":20,"total_time_minutes":40,"servings":4,"image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/daigaku-imo-boniato-caramelizado/portada.webp","gallery":[{"url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/daigaku-imo-boniato-caramelizado/portada.webp","alt":"Daigaku imo: batata-doce japonesa caramelizada na frigideira"}],"video_urls":[],"keywords":["Daigaku imo: batata-doce japonesa caramelizada na frigideira","Batata-doce japonesa com casca","Óleo vegetal"],"nutrition":{"calories":196,"protein_g":1.9,"carbs_g":33.0,"fat_g":6.8,"saturated_fat_g":0.7,"fiber_g":3.1,"sugar_g":16.7,"sodium_mg":165.0,"estimated":true,"serving_size":"1 das 4 porções","source":"USDA FoodData Central SR Legacy","source_url":"https://fdc.nal.usda.gov/download-datasets/","method":"Soma das referências pelo peso dos ingredientes, dividida pelas porções.","note":"Estimativa orientativa, não medição do prato pronto. Marcas e escorrimento alteram os valores; nutrientes com dados incompletos não são mostrados. Referências genéricas para mostarda preparada, creme, batata-doce, óleo e chocolate; variedades e marcas podem diferir."},"seo":{"title":"Daigaku imo: batata-doce japonesa caramelizada na frigideira","description":"Batata-doce japonesa de casca roxa com calda brilhante de açúcar e shoyu e gergelim preto. Esta versão combina micro-ondas e frigideira, sem fritura por imersão.","image_alt":"Daigaku imo: batata-doce japonesa caramelizada na frigideira","image_variants":["https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/daigaku-imo-boniato-caramelizado/portada-1x1.webp","https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/daigaku-imo-boniato-caramelizado/portada-4x3.webp","https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/daigaku-imo-boniato-caramelizado/portada-16x9.webp"],"faq":[{"q":"Posso usar batata-doce alaranjada?","a":"Sim, mas ela é mais macia e pode quebrar ao envolver na calda. Confira o ponto antes e mexa com delicadeza."},{"q":"Por que a cobertura ficou dura?","a":"A calda pode ter reduzido demais. Pare nas bolhas grandes e no brilho, sem chegar a um caramelo escuro."},{"q":"Dá para fazer sem micro-ondas?","a":"Cozinhe no vapor até ficar apenas macia e seque bem a superfície antes de dourar. Os tempos de preparo mudam."}],"rest_time_minutes":10},"published":false,"editorial_status":"draft","source_url":null,"source_post_id":null,"recipe_group_id":"938f01d5-5b22-4e76-9e2c-a2215f3cf548"}]$expected$::jsonb; x jsonb; v public.recipes; n int:=0;
BEGIN
 IF jsonb_array_length(j)<>7 THEN RAISE EXCEPTION 'Expected 7 records'; END IF;
 IF (SELECT count(*) FROM public.recipes r JOIN jsonb_array_elements(j) e ON r.public_path=e->>'public_path' AND r.recipe_group_id=(e->>'recipe_group_id')::uuid AND r.language=e->>'language')<>7 THEN RAISE EXCEPTION 'Group identity mismatch'; END IF;
 FOR x IN SELECT value FROM jsonb_array_elements(j) LOOP
  SELECT * INTO STRICT v FROM public.recipes WHERE public_path=x->>'public_path' AND recipe_group_id=(x->>'recipe_group_id')::uuid FOR UPDATE;
  IF v.published OR v.title IS DISTINCT FROM x->>'title' OR v.ingredients IS DISTINCT FROM x->'ingredients' OR v.steps IS DISTINCT FROM x->'steps' OR v.nutrition IS DISTINCT FROM x->'nutrition' OR v.seo IS DISTINCT FROM x->'seo' OR v.image_url IS DISTINCT FROM x->>'image_url' OR v.content_html IS DISTINCT FROM x->>'content_html' OR v.total_time_minutes IS DISTINCT FROM (x->>'total_time_minutes')::int THEN RAISE EXCEPTION 'Draft changed or already published: %',v.public_path; END IF;
 END LOOP;
 PERFORM set_config('request.jwt.claim.sub','2caf0bab-d7e8-4d52-9910-d79799c27072',true);
 IF NOT public.is_admin() THEN RAISE EXCEPTION 'Missing admin context'; END IF;
 FOR x IN SELECT value FROM jsonb_array_elements(j) LOOP
  SELECT * INTO STRICT v FROM public.recipes WHERE public_path=x->>'public_path' AND recipe_group_id=(x->>'recipe_group_id')::uuid;
  UPDATE public.recipes SET editorial_status='ready',ready_at=now(),reviewed_at=now(),reviewed_by='Codex editorial QA, owner-authorized 2026-10-28' WHERE id=v.id;
  PERFORM public.update_recipe(v.id,v.slug,v.title,v.excerpt,v.ingredients,v.steps,v.category,v.prep_time_minutes,v.cook_time_minutes,v.servings,v.image_url,true);
  UPDATE public.recipes SET editorial_status='published',published_by='Codex owner-authorized siete mercados 2026-10-28' WHERE id=v.id;
  n:=n+1;
 END LOOP;
 IF n<>7 THEN RAISE EXCEPTION 'Expected 7 publications'; END IF;
END $publish$;
